BRAND_ICONS = {}

# Load existing SVGs, applying colored overrides
for svg_path in sorted(icons_dir.glob("*.svg")):
    name = svg_path.stem
    if name in COLORED_SVGS:
        data = COLORED_SVGS[name]
    else:
        data = svg_path.read_text(encoding="utf-8")
    BRAND_ICONS[name] = f"data:image/svg+xml;base64,{base64.b64encode(data.encode()).decode()}"

# Handle PNG
png = icons_dir / "thanksdotdev.png"
if png.exists():
    BRAND_ICONS["thanksdotdev"] = f"data:image/png;base64,{base64.b64encode(png.read_bytes()).decode()}"
